import Link from 'next/link';
import { books } from '@/data/books';
import { BookArt } from '@/components/book-art';
import './landing.css';

function EditorialScene({kind}:{kind:'window'|'dream'|'still'|'hello'|'reading'}) {
  return <div className={`editorial-scene ${kind}`} aria-label={kind==='hello'?'Tender mother and newborn moment':kind==='reading'?'Mother and child reading together':'A quiet moment from the beginning of a family story'} role="img"><div className="scene-light"/><div className="scene-window"/><div className="scene-figure"/><div className="scene-belly"/><div className="scene-baby"/><div className="scene-letter">for our little love</div><div className="scene-garment"/><div className="scene-flowers">✿</div></div>
}

export default function Home(){const flagship=books[0]; return <main className="landing">
  <section className="campaign-hero wrap"><div className="campaign-copy"><p className="eyebrow">Little Adventures presents</p><h1>Before I met you,<br/>I already <i>loved you.</i></h1><p>A little story about the love that begins before hello.</p><div className="actions"><Link className="button" href="#storybook">Discover the storybook</Link><Link className="text-link" href="/about">Read our story →</Link></div></div><EditorialScene kind="window"/></section>
  <section className="moment dream-moment"><div className="moment-image"><EditorialScene kind="dream"/></div><div className="moment-copy"><p className="eyebrow">The moments before hello</p><h2>You were still <i>a dream.</i></h2><p>I imagined your face, your little hands, and the world we would discover together.</p></div></section>
  <section className="still-life wrap"><div className="still-copy"><p className="eyebrow">Already part of my world</p><h2>I hadn’t met you.<br/><i>Yet you were everywhere.</i></h2><p>In the little things I saved, the names I imagined, and the dreams I carried into every tomorrow.</p></div><EditorialScene kind="still"/></section>
  <section className="moment hello-moment"><div className="moment-copy"><p className="eyebrow">The first hello</p><h2>And then, there <i>you were.</i></h2><p>Every dream became a little person I could finally hold.</p></div><div className="moment-image"><EditorialScene kind="hello"/></div></section>
  <section className="storybook-reveal" id="storybook"><div className="wrap reveal-grid"><div className="reveal-book"><div className="book-plinth"/><BookArt book={flagship} large/></div><div className="reveal-copy"><p className="eyebrow">The storybook</p><h2>A little piece of<br/><i>your beginning.</i></h2><p>Made to hold the memories, dreams, and love that came before your first hello.</p><div className="book-detail"><span>Before I Met You</span><small>A little story about the love that began before hello.</small></div><Link className="button" href={`/stories/${flagship.slug}`}>Discover the storybook</Link></div></div></section>
  <section className="return-to wrap"><div className="return-copy"><p className="eyebrow">A story to return to</p><h2>One day, you’ll ask me<br/>how your story <i>began.</i></h2><p>And I’ll open this little book.</p><Link className="button" href="/stories">Explore Little Adventures</Link></div><EditorialScene kind="reading"/></section>
</main>}
